"""Demo: verify the deletion characterisation of forcing edges against brute
force on a family of small graphs, and print each graph's forcing spectrum."""
from __future__ import annotations
from itertools import combinations
from typing import FrozenSet, Iterator, List, Set, Tuple

Edge = FrozenSet[int]
Graph = Tuple[Set[int], Set[Edge]]


def graph(vs: List[int], es: List[Tuple[int, int]]) -> Graph:
    return (set(vs), {frozenset(e) for e in es if e[0] != e[1]})


def perfect_matchings(g: Graph) -> List[FrozenSet[Edge]]:
    V, E = g

    def bt(rem: Tuple[int, ...]) -> Iterator[FrozenSet[Edge]]:
        if not rem:
            yield frozenset()
            return
        a, rest = rem[0], rem[1:]
        for b in rest:
            if frozenset((a, b)) in E:
                sub = tuple(x for x in rest if x != b)
                for m in bt(sub):
                    yield m | {frozenset((a, b))}

    return list(bt(tuple(sorted(V))))


def forcing_bruteforce(g: Graph, u: int, v: int) -> bool:
    if frozenset((u, v)) not in g[1]:
        return False
    return sum(1 for m in perfect_matchings(g) if frozenset((u, v)) in m) == 1


def forcing_by_deletion(g: Graph, u: int, v: int) -> bool:
    V, E = g
    if frozenset((u, v)) not in E:
        return False
    sub = ({w for w in V if w not in (u, v)},
           {e for e in E if u not in e and v not in e})
    return len(perfect_matchings(sub)) == 1


if __name__ == "__main__":
    tests = {
        "P6": graph(list(range(6)), [(i, i + 1) for i in range(5)]),
        "C6": graph(list(range(6)), [(i, (i + 1) % 6) for i in range(6)]),
        "K6": graph(list(range(6)), list(combinations(range(6), 2))),
    }
    for name, g in tests.items():
        agree = all(forcing_bruteforce(g, *tuple(e)) == forcing_by_deletion(g, *tuple(e))
                    for e in g[1])
        nf = sum(forcing_by_deletion(g, *tuple(e)) for e in g[1])
        print(f"{name}: brute==deletion? {agree}; forcing edges = {nf}/{len(g[1])}")

