function FORCING_SPECTRUM(G, IS_FORCING):
    S <- empty list
    for each edge {u,v} in E(G):
        if IS_FORCING(G, u, v): append {u,v} to S
    return S

function FORCING_FRACTION(G, IS_FORCING):
    if E(G) empty: return 0
    return |FORCING_SPECTRUM(G, IS_FORCING)| / |E(G)|

function UNIQUE_PM(G):
    found <- empty list
    function BT(remaining, acc):
        if |found| > 1: return
        if remaining empty: append acc to found; return
        a <- first(remaining)
        for b in remaining, b != a:
            if {a,b} in E(G):
                BT(remaining without a and b, acc + {a,b})
    BT(V(G), empty)
    return found[0] if |found| == 1 else NONE

